        shayariItem(468, "न जाने कितनी बार टूटा हूँ मैं अकेले में,\nपर हर बार तेरे भरोसे ने मुझे फिर से खड़ा कर दिया।", "_ शायरी", cat, "हिम्मत"),
        shayariItem(469, "इंसान की नज़र में ग़लतियाँ याद रहती हैं,\nमेरे खुदा की नज़र में तो बस एक सच्चा पश्चाताप काफ़ी है।", "_ शायरी", cat, "माफ़ी"),
        shayariItem(470, "तेरी दुनिया में रंग बहुत हैं ऐ मालिक,\nबस मेरे हिस्से में भी थोड़ी सी खुशियों की बहार लिख दे।", "_ शायरी", cat, "बहार"),
        shayariItem(471, "अगर कोई काम तुम्हारी मर्ज़ी से न हो तो खुश हो जाना,\nक्योंकि अब वो तेरे रब की मर्ज़ी से होने वाला है।", "_ शायरी", cat, "यकीन"),
        shayariItem(472, "सारे जहाँ की दौलत एक तरफ़,\nऔर मेरे मालिक की एक नज़र-ए-करम एक तरफ़।", "_ शायरी", cat, "करम"),
        shayariItem(473, "जो लोग चुपचाप रब पर भरोसा रखते हैं,\nउनकी किस्मत एक दिन अचानक चमक उठती है।", "_ शायरी", cat, "किस्मत"),
        shayariItem(474, "हर दर्द की दवा है तेरे पास मेरे रब,\nबस तू अपनी रहमत की एक बूँद बरसा दे।", "_ शायरी", cat, "दवा"),
        shayariItem(475, "तसल्ली रख मेरे दिल ये बुरा वक़्त भी गुज़र जाएगा,\nजिसने तुझे बनाया है वो तुझे बिखरने नहीं देगा।", "_ शायरी", cat, "तसल्ली"),
        shayariItem(476, "कभी-कभी रब हमें इसलिए खाली हाथ कर देता है,\nताकि हम दुनिया की भीड़ से निकलकर उसे पहचान सकें।", "_ शायरी", cat, "पहचान"),
        shayariItem(477, "मेरी ख़ामियों को नज़रअंदाज़ करके गले लगाया तूने,\nऐ मेरे रब तेरे जैसा मेहरबान कोई नहीं।", "_ शायरी", cat, "मेहरबान"),
        shayariItem(478, "दुआ में दूसरों की ख़ुशी भी माँग लिया करो,\nकभी-कभी किसी और की दुआ भी हमें लग जाती है।", "_ शायरी", cat, "दुआ"),
        shayariItem(479, "हर मुश्किल के बाद आसानी का वादा है रब का,\nबस हिम्मत मत हारना सफ़र अभी बाकी है।", "_ शायरी", cat, "वादा"),
        shayariItem(480, "दिल में जब डर हो तो आंखें बंद करके रब को याद कर लेना,\nसारा बोझ पल भर में हल्का हो जाएगा।", "_ शायरी", cat, "सुकून"),
        shayariItem(481, "तेरे दर के फ़कीर भी बादशाहों से कम नहीं,\nजिन्हें तेरी रहमत मिल जाए उन्हें किसी और की ज़रूरत नहीं।", "_ शायरी", cat, "रहमत"),
        shayariItem(482, "सब कुछ पाकर भी खालीपन रहे तो समझ लेना,\nदिल में कहीं न कहीं रब की याद की कमी है।", "_ शायरी", cat, "याद"),
        shayariItem(483, "नज़रों से ओझल है मगर हर साँस के पास है,\nमेरे खुदा का होना ही मेरे जीने की आस है।", "_ शायरी", cat, "आस"),
        shayariItem(484, "ज़िंदगी के कागज़ पर अपनी मर्ज़ी से क्या लिखूँ मैं,\nमेरे मालिक तेरा लिखा हर फ़ैसला सिर आँखों पर है।", "_ शायरी", cat, "फ़ैसला"),
        shayariItem(485, "जिस दिन तूने किसी की मदद करके मुस्कुराया होगा,\nउस दिन ऊपर वाले ने भी तुझे प्यार से देखा होगा।", "_ शायरी", cat, "मदद"),
        shayariItem(486, "अंधेरी रातों में तारे गवाह हैं मेरी दुआओं के,\nमेरा रब एक दिन ज़रूर मेरी झोली ख़ुशियों से भरेगा।", "_ शायरी", cat, "तारे"),
        shayariItem(487, "हम छोटे हैं और गलतियाँ भी बड़ी करते हैं,\nपर तेरी रहमत का समंदर हमारी हर भूल से बड़ा है।", "_ शायरी", cat, "बख़्शिश"),
        shayariItem(488, "जो दिल किसी का घर न तोड़ पाए,\nसमझो उस दिल में खुद रब बसता है।", "_ शायरी", cat, "दिल"),
        shayariItem(489, "वक़्त बुरा हो तो घबराना मत मेरे दोस्त,\nऊपर वाला तेरे सब्र की कीमत तुझे सूद समेत लौटाएगा।", "_ शायरी", cat, "सब्र"),
        shayariItem(490, "न कोई तावीज़ न कोई जादू काम आता है,\nमुश्किल घड़ी में बस रब का नाम ही काम आता है।", "_ शायरी", cat, "नाम"),
        shayariItem(491, "मेरे मौला तेरी दुनिया में अमन और प्यार बना रहे,\nहर घर में रोटी हो और हर चेहरे पर मुस्कान सजी रहे।", "_ शायरी", cat, "अमन"),
        shayariItem(492, "जितना भरोसा खुद पर है उससे कहीं ज़्यादा तुझ पर है,\nऐ मेरे खुदा तू कभी मेरी लाज नहीं जाने देगा।", "_ शायरी", cat, "लाज"),
        shayariItem(493, "कहते हैं ऊपर वाला सबकी सुनता है,\nबस आवाज़ गले से नहीं सीधे रूह से आनी चाहिए।", "_ शायरी", cat, "रूह"),
        shayariItem(494, "रास्ते अगर पथरीले हैं तो क्या ग़म है,\nमंज़िल तक पहुँचाने वाला मेरा रब बड़ा हमदम है।", "_ शायरी", cat, "रास्ते"),
        shayariItem(495, "कभी अभिमान मत करना अपनी ताक़त या दौलत पर,\nवो जिसे चाहे पल में ज़मीन पर ला दे और जिसे चाहे आसमान दे दे।", "_ शायरी", cat, "सीख"),
        shayariItem(496, "सजदे में बिताया एक पल ज़िंदगी की हज़ार दौलतों से कीमती है,\nवहाँ इंसान दुनिया से कटकर अपने रब से जुड़ जाता है।", "_ शायरी", cat, "सजदा"),
        shayariItem(497, "जो दिल से निकलती है दुआ किसी मजबूर के लिए,\nरब के दर पर वो सबसे पहले मंज़ूर होती है।", "_ शायरी", cat, "दुआ"),
        shayariItem(498, "तेरे करम की छाया रहे मेरे घर पर हमेशा,\nयही एक अरदास है मेरी हर सुबह हर शाम।", "_ शायरी", cat, "अरदास"),
        shayariItem(499, "जब भी लगे दुनिया में कोई अपना नहीं रहा,\nआसमान की तरफ़ देखना वहाँ बैठा मालिक सिर्फ़ तेरा है।", "_ शायरी", cat, "अपनापन"),
        shayariItem(500, "अल्फ़ाज़ कम पड़ जाते हैं तेरी तारीफ़ लिखते हुए,\nऐ मेरे रब तू हर हाल में सबसे बेहतर करने वाला है।", "_ शायरी", cat, "शुकराना")
    )
}
